12|static int buffer_read_fn(spng_ctx *ctx, void *user, void *dest, size_t length)
13|{
14|    struct buf_state *state = (struct buf_state*)user;
15|    (void)ctx;
16|
17|    if(length > state->bytes_left) return SPNG_IO_EOF;
18|
19|    memcpy(dest, state->data, length);
20|
21|    state->bytes_left -= length;
22|    state->data += length;
23|
24|    return 0;
25|}
