30|int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
31|{
32|    if(size < 4) return 0;
33|
34|    int flags = data[size - 1];
35|    int fmt = data[size - 3] | (data[size - 2] << 8);
36|    int stream = data[size - 4] & 1;
37|    int progressive = data[size - 4] & 2;
38|    int file_stream = data[size - 4] & 4;
39|    int discard = data[size - 4] & 8;
40|
41|    size -= 4;
42|
43|    int ret;
44|    unsigned char *out = NULL;
45|    FILE *file = NULL;
46|
47|    spng_ctx *ctx = spng_ctx_new(SPNG_CTX_IGNORE_ADLER32);
48|    if(ctx == NULL) return 0;
49|
50|    struct spng_ihdr ihdr;
51|    struct spng_plte plte;
52|    struct spng_trns trns;
53|    struct spng_chrm chrm;
54|    struct spng_chrm_int chrm_int;
55|    double gamma;
56|    struct spng_iccp iccp;
57|    struct spng_sbit sbit;
58|    uint8_t srgb_rendering_intent;
59|    struct spng_text text[4] = {0};
60|    struct spng_bkgd bkgd;
61|    struct spng_hist hist;
62|    struct spng_phys phys;
63|    struct spng_splt splt[4] = {0};
64|    struct spng_time time;
65|    struct spng_unknown_chunk chunks[4] = {0};
66|    uint32_t n_text = 4, n_splt = 4, n_chunks = 4;
67|
68|    struct buf_state state;
69|    state.data = data;
70|    state.bytes_left = size;
71|
72|    if(stream)
73|    {
74|        if(file_stream)
75|        {
76|#if defined(SPNGT_HAVE_FMEMOPEN)
77|            file = fmemopen((void*)data, size, "rb");
78|
79|            if(file == NULL) goto err;
80|#endif
81|            ret = spng_set_png_file(ctx, file);
82|        }
83|        else ret = spng_set_png_stream(ctx, buffer_read_fn, &state);
84|    }
85|    else ret = spng_set_png_buffer(ctx, (void*)data, size);
86|
87|    if(ret) goto err;
88|
89|    spng_set_image_limits(ctx, 200000, 200000);
90|
91|    spng_set_chunk_limits(ctx, 4 * 1000 * 1000, 8 * 1000 * 1000);
92|
93|    spng_set_crc_action(ctx, SPNG_CRC_USE, discard ? SPNG_CRC_DISCARD : SPNG_CRC_USE);
94|
95|    spng_set_option(ctx, SPNG_KEEP_UNKNOWN_CHUNKS, 1);
96|
97|    size_t out_size;
98|    if(spng_decoded_image_size(ctx, fmt, &out_size)) goto err;
99|
100|    if(out_size > 80000000) goto err;
101|
102|    out = (unsigned char*)malloc(out_size);
103|    if(out == NULL) goto err;
104|
105|    spng_get_ihdr(ctx, &ihdr);
106|    spng_get_plte(ctx, &plte);
107|    spng_get_trns(ctx, &trns);
108|    spng_get_chrm(ctx, &chrm);
109|    spng_get_chrm_int(ctx, &chrm_int);
110|    spng_get_gama(ctx, &gamma);
111|    spng_get_iccp(ctx, &iccp);
112|    spng_get_sbit(ctx, &sbit);
113|    spng_get_srgb(ctx, &srgb_rendering_intent);
114|
115|    if(!spng_get_text(ctx, text, &n_text))
116|    {/* Up to 4 entries were read, get the actual count */
117|        spng_get_text(ctx, NULL, &n_text);
118|
119|        uint32_t i;
120|        for(i=0; i < n_text; i++)
121|        {/* All strings should be non-NULL */
122|            if(text[i].text == NULL ||
123|               text[i].keyword[0] == '\0' ||
124|               text[i].language_tag == NULL ||
125|               text[i].translated_keyword == NULL ||
126|               memchr(text[i].keyword, 0, 80) == NULL)
127|            {
128|                spng_ctx_free(ctx);
129|                free(out);
130|                return 1;
131|            }
132|            /* This shouldn't cause issues either */
133|            text[i].length = strlen(text[i].text);
134|        }
135|    }
136|
137|    spng_get_bkgd(ctx, &bkgd);
138|    spng_get_hist(ctx, &hist);
139|    spng_get_phys(ctx, &phys);
140|
141|    if(!spng_get_splt(ctx, splt, &n_splt))
142|    {/* Up to 4 entries were read, get the actual count */
143|        spng_get_splt(ctx, NULL, &n_splt);
144|
145|        uint32_t i;
146|        for(i=0; i < n_splt; i++)
147|        {
148|            if(splt[i].name[0] == '\0' ||
149|               splt[i].entries == NULL ||
150|               memchr(splt[i].name, 0, 80) == NULL)
151|            {
152|                spng_ctx_free(ctx);
153|                free(out);
154|                return 1;
155|            }
156|        }
157|    }
158|
159|    if(!spng_get_unknown_chunks(ctx, chunks, &n_chunks))
160|    {
161|        spng_get_unknown_chunks(ctx, NULL, &n_chunks);
162|
163|        uint32_t i;
164|        for(i=0; i < n_chunks; i++)
165|        {
166|            if( (chunks[i].length && !chunks[i].data) ||
167|                (!chunks[i].length && chunks[i].data) )
168|            {
169|                spng_ctx_free(ctx);
170|                free(out);
171|                return 1;
172|            }
173|        }
174|    }
175|
176|    if(progressive)
177|    {
178|        if(spng_decode_image(ctx, NULL, 0, fmt, flags | SPNG_DECODE_PROGRESSIVE)) goto err;
179|
180|        size_t ioffset, out_width = out_size / ihdr.height;
181|        struct spng_row_info ri;
182|
183|        do
184|        {
185|            if(spng_get_row_info(ctx, &ri)) break;
186|
187|            ioffset = ri.row_num * out_width;
188|
189|        }while(!spng_decode_row(ctx, out + ioffset, out_size));
190|    }
191|    else if(spng_decode_image(ctx, out, out_size, fmt, flags)) goto err;
192|
193|    spng_get_time(ctx, &time);
194|
195|err:
196|    spng_ctx_free(ctx);
197|    free(out);
198|    if(file != NULL) fclose(file);
199|
200|    return 0;
201|}

